{"g":4,"b":4,"k":"g","q":"Hvad er datid af 'find'?","o":["finded","found","fand","founded"],"a":"found","r":"'Find' er uregelmæssig: find → found = fandt."},
{"g":4,"b":4,"k":"g","q":"Hvad er datid af 'tell'?","o":["told","telled","tolled","tells"],"a":"told","r":"'Tell' er uregelmæssig: tell → told = fortalte."},
