{"g":4,"b":4,"k":"o","q":"Hvad betyder 'surprised'?","o":["overgivet","sur","sikker","overrasket"],"a":"overrasket","r":"'Surprised' betyder overrasket. 'Surprise!' = overraskelse!"},
