{"g":4,"b":4,"k":"o","q":"Hvad betyder 'safe'?","o":["saft","sej","syg","sikker"],"a":"sikker","r":"'Safe' betyder sikker eller i sikkerhed. Det modsatte er 'dangerous' — farlig."},
{"g":4,"b":4,"k":"o","q":"Hvad betyder 'enough'?","o":["ingen","endnu","nok","ensom"],"a":"nok","r":"'Enough' betyder nok: 'I have enough money' = jeg har penge nok."},
{"g":4,"b":4,"k":"o","q":"Hvad betyder 'almost'?","o":["altid","næsten","mest","alle"],"a":"næsten","r":"'Almost' betyder næsten: 'It's almost ten' = klokken er næsten ti."},
{"g":4,"b":4,"k":"o","q":"Hvad betyder 'suddenly'?","o":["pludselig","sjældent","langsomt","søndag"],"a":"pludselig","r":"'Suddenly' betyder pludselig."},
