{"g":4,"b":4,"k":"o","q":"Hvad betyder 'birthday cake'?","o":["fødselsdagsgave","fødselsdagskage","fødselsdagsfest","fødselsdagssang"],"a":"fødselsdagskage","r":"'Birthday' + 'cake' = fødselsdagskage."},
{"g":4,"b":4,"k":"o","q":"Hvad betyder 'toothbrush'?","o":["tandbørste","tandpasta","tandlæge","hårbørste"],"a":"tandbørste","r":"'Tooth' (tand) + 'brush' (børste) = tandbørste."},
