{"g":4,"b":4,"k":"o","q":"Hvad betyder 'sunglasses'?","o":["solcreme","solbriller","solskin","solsikke"],"a":"solbriller","r":"'Sun' (sol) + 'glasses' (briller) = solbriller."},
{"g":4,"b":4,"k":"o","q":"Hvad betyder 'raincoat'?","o":["regnfrakke","regnbue","regnvejr","regnorm"],"a":"regnfrakke","r":"'Rain' (regn) + 'coat' (frakke) = regnfrakke."},
{"g":4,"b":4,"k":"h","q":"Hvad betyder 'It's up to you'?","o":["Det er oppe hos dig","Det er din tur","Det er dit problem","Det er op til dig"],"a":"Det er op til dig","r":"'It's up to you' = du bestemmer."},
{"g":4,"b":4,"k":"h","q":"Hvad betyder 'Never mind'?","o":["Glem aldrig","Pas på","Det gør ikke noget","Tænk dig om"],"a":"Det gør ikke noget","r":"'Never mind' bruges, når noget ikke er vigtigt: glem det, det gør ikke noget."},
